import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays, endOfMonth } from './dates.js';

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, terms: string, dueDate: string, status: 'draft', lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  const termsValidation = validateTerms(terms);
  if (!termsValidation.ok) return termsValidation;

  if (!lines || !Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  const tierDiscount = TIER_DISCOUNTS[customerResult.value.tier];

  const enrichedLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    const discountValidation = validateDiscount(line.discountPercent);
    if (!discountValidation.ok) return discountValidation;

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;

    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  let dueDate;
  if (terms === 'NET14') {
    dueDate = addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    dueDate = addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    dueDate = endOfMonth(issueDate);
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    terms,
    dueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line (qty × unitPrice).
 * @param {{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }} line
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} Discount in cents
 */
export function lineDiscount(line) {
  if (!line.discountPercent || line.discountPercent === 0) {
    return 0;
  }
  const total = lineTotal(line);
  return roundCents(total * line.discountPercent / 100);
}

/**
 * Calculate VAT for a single line (computed on the amount after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number} VAT in cents
 */
export function lineVAT(line) {
  if (!line.vatRate || line.vatRate === 0) {
    return 0;
  }
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = total - discount;
  return roundCents(amountAfterDiscount * line.vatRate / 100);
}

/**
 * Calculate subtotal, discount, VAT, voucher, and total for an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} Amounts in cents
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  let vat = 0;

  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
    discount += lineDiscount(line);
    vat += lineVAT(line);
  }

  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);

  return {
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    vat: Math.max(0, vat),
    voucher: Math.max(0, voucher),
    total,
  };
}

/**
 * Add a line item to a draft invoice. If the SKU already exists, increase its qty.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  const discountValidation = validateDiscount(discountPercent);
  if (!discountValidation.ok) return discountValidation;

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const tierDiscount = TIER_DISCOUNTS[customerResult.value.tier];
  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    const lineDiscountPercent = discountPercent !== undefined ? discountPercent : tierDiscount;
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: lineDiscountPercent,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    status: 'draft',
    lines: newLines,
  });
}

